  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_vehicles_external_id` (`external_id`),
  KEY `idx_vehicles_type_model` (`vehicle_type_model_id`),
  KEY `idx_vehicles_current_status` (`current_status_id`),
  KEY `idx_vehicles_last_seen_at` (`last_seen_at`),
  CONSTRAINT `fk_vehicles_current_status` FOREIGN KEY (`current_status_id`) REFERENCES `statuses` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_vehicles_type_model` FOREIGN KEY (`vehicle_type_model_id`) REFERENCES `vehicle_type_models` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=575 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
